dtsPropsFor.ContactForm:
/** Google reCAPTCHA v2 site key, passed straight to the captcha widget. */
RECAPTCHA_SITE_KEY: string;
/** The captcha only renders when this is exactly "production". Any other value renders the form without it. */
NODE_ENV: string;

dtsPropsFor.ContactSection:
/** Contact rows listed beside the form. Each row is an icon + text, linked when `link` is set. */
contactInfoData: Array<{
  id: string;
  /** Icon name from react-icons/fa6, e.g. "FaGithub". Rendered via DynamicBrandedIcon. */
  icon: string;
  text: string;
  /** A "mailto:" link opens in place; anything else opens in a new tab. */
  link?: string;
}>;
/** Google reCAPTCHA v2 site key, forwarded to the embedded ContactForm. */
RECAPTCHA_SITE_KEY: string;
/** Forwarded to ContactForm — the captcha renders only on the exact string "production". */
NODE_ENV: string;

dtsPropsFor.DynamicBrandedIcon:
/** Icon name from react-icons/fa6, e.g. "FaGithub" | "FaLinkedin" | "FaXTwitter". An unknown name falls back to FaUser rather than throwing. */
name: string;
/** Remaining props are spread onto the underlying react-icons element. The component sets className="shrink-0" first, so passing className replaces it. */
size?: string | number;
color?: string;
className?: string;
title?: string;

dtsPropsFor.EducationHistory:
educationHistoryData: Array<{
  id: string;
  course: string;
  organizationId: string;
  /** Free-text range as authored in Notion, e.g. "Feb 2011 - Dec 2015". */
  date: string;
  description: Array<{
    id: string;
    type: "text" | "mention" | "equation";
    text?: { content: string; link?: { url?: string } };
    equation?: string;
    annotations: {
      bold: boolean;
      italic: boolean;
      strikethrough: boolean;
      underline: boolean;
      code: boolean;
      color: "default" | "gray" | "brown" | "orange" | "yellow" | "green" | "blue" | "purple" | "pink" | "red" | "gray_background" | "brown_background" | "orange_background" | "yellow_background" | "green_background" | "blue_background" | "purple_background" | "pink_background" | "red_background";
    };
  }>;
}>;
/** Organizations keyed by id. Every entry's organizationId must resolve here — a miss throws while rendering the logo. */
organizationsDataHash: { [key: string]: { id: string; name: string; logo: string; link: string } };

dtsPropsFor.HistorySection:
/** Anchor id for the section, used by the nav's in-page links. */
id: string;
/** Section header text, rendered mono uppercase. */
title: string;
/** One timeline row each, in display order. With 2+ entries a connecting rail is drawn; a single entry renders without one. */
entries: Array<{
  id: string;
  /** Free-text range as authored in Notion, e.g. "Jan 2020 - Present". */
  date: string;
  /** Role, course — whatever follows the organization name. */
  detail: string;
  /** Required: the row reads .logo, .name and .link unguarded. */
  organization: { id: string; name: string; logo: string; link: string };
  /** Revealed by the row's own "see more" toggle; collapsed on first paint. */
  description: Array<{
    id: string;
    type: "text" | "mention" | "equation";
    text?: { content: string; link?: { url?: string } };
    equation?: string;
    annotations: {
      bold: boolean;
      italic: boolean;
      strikethrough: boolean;
      underline: boolean;
      code: boolean;
      color: "default" | "gray" | "brown" | "orange" | "yellow" | "green" | "blue" | "purple" | "pink" | "red" | "gray_background" | "brown_background" | "orange_background" | "yellow_background" | "green_background" | "blue_background" | "purple_background" | "pink_background" | "red_background";
    };
  }>;
}>;

