dtsPropsFor.LanguagesSection:
/** One row per language. `level` is prose ("Native", "Professional working proficiency"), not a score. */
languages: Array<{
  id: string;
  name: string;
  level: string;
  /** Display order is the caller's job — the component renders the array as given. */
