dtsPropsFor.Portfolio:
portfolioData: Array<{
  id: string;
  title: string;
  /** When set, the whole card becomes a link opening in a new tab. */
  link?: string;
  tags: string[];
  image?: string;
  embed?: string;
}>;
/** The full tag vocabulary offered as filter chips, independent of which tags the items carry. */
tags: string[];

dtsPropsFor.Section:
/** Anchor id, used by the nav's in-page links. The header parks under the nav via --nav-h. */
id?: string;
/** Header text, rendered mono uppercase on surface-2. */
title: string;
/** Rendered at the right end of the header row — filter buttons, counts, links. */
actions?: React.ReactNode;
/** Rendered inside the sticky block, under the header row. Anything the header opens belongs here — left in `children` it would appear at its original place in the document, off-screen above a pinned header. */
subheader?: React.ReactNode;
/** Appended to the section element's own classes. */
className?: string;
/** The section body, below the header. */
children: React.ReactNode;

dtsPropsFor.SkillsSection:
/** One gauge row per skill. `percentage` drives the bar width; 100 fills the bar with ink instead of accent. */
skills: Array<{
  id: string;
  name: string;
  /** 0–100. Rendered as both the bar width and the numeral on the right. */
  percentage: number;
}>;
